'use strict';
const byId=id=>document.getElementById(id);
const statuses={failed:'失败',running:'运行中',awaiting_human_review:'等待复核',human_reviewed:'复核已提交',completed:'完成',skipped:'跳过',pending:'待执行'};
let runs=[],selected='',generation=0;
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);if(cls)n.className=cls;return n;}
function time(value){if(!value)return '—';const d=new Date(value);return isNaN(d)?String(value):d.toLocaleString('zh-CN');}
function duration(value){return value===null||value===undefined?'—':value+' 秒';}
async function api(path){const response=await fetch(path),data=await response.json();if(!response.ok)throw new Error(data.error||'读取失败');return data;}
function table(headers,rows){const t=el('table'),head=el('tr');headers.forEach(x=>head.append(el('th',x)));const thead=el('thead');thead.append(head);t.append(thead);const body=el('tbody');rows.forEach(row=>{const tr=el('tr');row.forEach(value=>tr.append(el('td',value??'—')));body.append(tr);});t.append(body);return t;}
function list(){const shown=runs.filter(r=>byId('status-filter').value==='all'||r.status===byId('status-filter').value);const nav=byId('log-runs');nav.replaceChildren();for(const run of shown){const b=el('button',`${run.sample_id||'未取得样本'} · ${statuses[run.status]||run.status}`,run.id===selected?'selected':'');b.setAttribute('aria-pressed',String(run.id===selected));b.append(el('small',run.id),el('small',time(run.started_at)));b.onclick=()=>choose(run.id);nav.append(b);}if(!shown.length)nav.append(el('p','当前筛选下没有流程。'));return shown;}
async function choose(id){selected=id;list();const version=++generation;byId('log-detail').replaceChildren(el('p','正在读取…'));try{const d=await api('/api/logs/run?run='+encodeURIComponent(id));if(version!==generation)return;const view=byId('log-detail');view.replaceChildren(el('h2',`${d.sample_id||'未取得样本'} · ${statuses[d.status]||d.status}`,d.status==='failed'?'failure':''),el('p',d.id,'log-id'),el('p',`模式 ${d.mode} · 总耗时 ${duration(d.duration_seconds)} · 模型阶段 ${d.model_stage_attempts??'—'} / ${d.model_stage_budget??'—'}`,'helper'));if(d.refinement){const r=d.refinement,box=el('div',undefined,'table-scroll');box.append(table(['检查对象','验证状态','反馈理由'],r.tasks.map(t=>[t.target,{supported:'支持',revise:'需修正',insufficient_evidence:'证据不足'}[t.status]||t.status,t.reason])));view.append(el('h3','受控返修'),el('p',`已开始 ${r.rounds_started} / ${r.max_rounds} 轮；来源流程已尝试 ${r.parent_model_stage_attempts} 个模型阶段，本轮尝试数见上方。`,'helper'),el('p',r.stop_reason),box);}if(d.plan){const planBox=el('div',undefined,'table-scroll');planBox.append(table(['任务','角色 / 工具','动作','调度理由'],d.plan.tasks.map(t=>[t.name,`${t.role} / ${t.tool}`,t.action==='skip'?'跳过':'执行',t.reason])));view.append(el('h3','本轮任务计划'),el('p',d.plan.goal,'helper'),planBox);}view.append(el('h3','停止原因 / 当前边界'),el('pre',d.stop_reason||'没有记录停止原因。'));const box=el('div',undefined,'table-scroll');box.append(table(['阶段','状态','耗时','错误或说明'],d.stages.map(s=>[s.name,statuses[s.status]||s.status,duration(s.duration_seconds),s.error||'—'])));view.append(el('h3','阶段记录'),box,el('h3','事件时间线'));const events=el('div',undefined,'table-scroll');events.append(table(['时间','事件','阶段','错误或说明'],d.events.map(e=>[time(e.time),e.event,e.stage||'—',e.error||e.reason||'—'])));view.append(events,el('p',`显示 ${d.events.length} 条事件${d.events_truncated?'（已截取末尾）':''}；无法解析 ${d.invalid_event_lines} 行。`,'helper'));}catch(error){if(version===generation)byId('log-detail').replaceChildren(el('p',error.message,'failure'));}}
async function refresh(){byId('refresh').disabled=true;byId('log-message').textContent='';try{const data=await api('/api/logs');runs=data.runs;const metrics=byId('metrics');metrics.replaceChildren();for(const [name,count] of [['已读取流程',runs.length],['失败',runs.filter(r=>r.status==='failed').length],['等待复核',runs.filter(r=>r.status==='awaiting_human_review').length],['复核已提交',runs.filter(r=>r.status==='human_reviewed').length]]){const card=el('div',undefined,'log-metric');card.append(el('strong',count),el('span',name));metrics.append(card);}byId('list-scope').textContent=`${data.scope}。无法读取 ${data.unreadable} 项${data.limited?'，目录已截断':''}。`;const shown=list();if(shown.length)await choose(shown.some(r=>r.id===selected)?selected:shown[0].id);else{++generation;byId('log-detail').replaceChildren(el('p','暂无匹配流程。'));}const http=await api('/api/logs/requests');byId('requests').replaceChildren(table(['时间','请求编号','方法 / 接口','状态码','毫秒'],http.requests.map(r=>[time(r.time),r.request_id,`${r.method} ${r.route}`,r.status,r.duration_ms])));}catch(error){byId('log-message').textContent=error.message;}finally{byId('refresh').disabled=false;}}
byId('refresh').onclick=refresh;
byId('status-filter').onchange=()=>{const shown=list();if(shown.length)choose(shown[0].id);else{++generation;byId('log-detail').replaceChildren(el('p','暂无匹配流程。'));}};
refresh();
